var counter = new Counter(40);
counter.Add(2);
Console.WriteLine(counter.Value);

partial class Counter
{
    public int Value { get; private set; }
    public Counter(int value) { Value = value; }
}

partial class Counter
{
    public void Add(int amount) { Value += amount; }
}
